  css: string;
  instance: {
    [Key in ThemeName]?: Theme;
  };
  theme: {
    breakpoints: Breakpoint;
    colors: Partial<ColorToken> & { [Key in ThemeName]?: Partial<ColorToken> };
    fonts: Typography;
