> &
  React.PropsWithChildren<AsComponentProps<Component> & Props>;
type PrefixedVariant<
  Variant extends string,
  Prefix extends string,
> = `${Prefix}-${Variant}`;
interface StyleConfig<Variant extends string> {
  readonly base: string;
